// The agents' browser reads a page the way Playwright MCP does (docs/agent-browser.md): an
// accessibility snapshot in Playwright's own YAML, with a ref on every element an agent can act on,
// made by Playwright's own in-page script (vendored in src/generated by scripts/vendor-playwright.mjs).
// It runs in the runtime's isolated world, so the page can't see it or patch what it relies on, and
// the refs it puts on elements are that world's own. Two hooks keep Valet's rule that a snapshot
// shows what a person can see: nothing hidden, and controls named by their visible words.

import { INJECTED_SOURCE } from './generated/playwright-injected'
import { HIDDEN } from './scratch-scripts'
import { jsonLiteral } from './scripts'

/** Set in the isolated world once the injected script has been booted for this document. */
const GLOBAL = '__valetAria'

// A control's visible words win over an aria-label, title or alt no one sees; those only name an
// interactive element that shows no words (an icon button). Anything else keeps a name only if a
// person can read it on the element. A picture's alt names nothing outside a link or button.
const NAME = `(el, name) => {
  const clean = (s) => String(s || '').replace(/\\s+/g, ' ').trim()
  const tag = el.tagName.toLowerCase()
  if (tag === 'input' || tag === 'select' || tag === 'textarea') return name
  if (tag === 'img') return el.closest('a,button,[role=link],[role=button]') ? name : ''
  const visible = clean(typeof el.innerText === 'string' ? el.innerText : el.textContent)
  if (name === '' || visible.includes(clean(name))) return name
  const interactive = el.matches('a,button,summary,[role=button],[role=link],[role=tab],[role=menuitem],[role=option],[role=checkbox],[role=radio],[role=switch]')
  if (visible !== '') return interactive ? visible : ''
  return interactive ? name : ''
}`

// Hidden by itself; the patched walk skips the whole subtree, so a child of a hidden parent never
// shows. A closed select's options have no boxes of their own but are what the select offers.
const BOOT = `(() => {
  if (globalThis.${GLOBAL}) return true
  const hidden = ${HIDDEN}
  globalThis.__valetHidden = (el) => {
    const tag = el.tagName.toLowerCase()
    if ((tag === 'option' || tag === 'optgroup') && el.closest('select') !== null) return hidden(el.closest('select'))
    return hidden(el)
  }
  globalThis.__valetName = ${NAME}
  const module = {}
  ${INJECTED_SOURCE}
  globalThis.${GLOBAL} = new (module.exports.InjectedScript())(globalThis, {
    isUnderTest: false, sdkLanguage: 'javascript', frameSeq: 0, testIdAttributeName: 'data-testid',
    stableRafCount: 1, browserName: 'chromium', shouldPrependErrorPrefix: false, isUtilityWorld: true,
    customEngines: [],
  })
  return true
})()`

/** Whether this document already has the injected script; the boot is sent only when it hasn't. */
export const ariaBootedScript = (): string => `Boolean(globalThis.${GLOBAL})`
export const ariaBootScript = (): string => BOOT

/** A ref from a snapshot (e12), or a CSS selector, as Playwright MCP's `target` takes either. */
const ELEMENT = `(target) => {
  const v = globalThis.${GLOBAL}
  if (/^e\\d{1,6}$/.test(target)) {
    const el = v.querySelector(v.parseSelector('aria-ref=' + target), document, false)
    return el || { error: 'stale' }
  }
  try { return document.querySelector(target) || { error: 'not-found' } } catch { return { error: 'invalid-selector' } }
}`

const SNAPSHOT = `(options) => {
  const v = globalThis.${GLOBAL}
  let root = document.body || document.documentElement
  if (options.target !== null) {
    const found = (${ELEMENT})(options.target)
    if (found.error) return found
    root = found
  }
  const yaml = v.ariaSnapshot(root, { mode: 'ai', depth: options.depth === null ? undefined : options.depth })
  return { url: String(location.href).slice(0, 2000), title: String(document.title).slice(0, 300), yaml }
}`

/**
 * Where to send trusted input for an element: scrolled into view, its centre in viewport
 * coordinates, and what kind of field it is (typing refuses passwords and one-time codes).
 */
const POINT = `(target) => {
  const el = (${ELEMENT})(target)
  if (el.error) return el
  if (globalThis.__valetHidden(el)) return { error: 'hidden' }
  el.scrollIntoView({ block: 'center', inline: 'center', behavior: 'instant' })
  const rect = el.getBoundingClientRect()
  if (rect.width === 0 || rect.height === 0) return { error: 'hidden' }
  const x = rect.left + rect.width / 2
  const y = rect.top + rect.height / 2
  const top = document.elementFromPoint(x, y)
  const lower = (name) => (el.getAttribute(name) || '').toLowerCase()
  const tag = el.tagName.toLowerCase()
  return {
    x, y,
    covered: top !== null && top !== el && !el.contains(top) && !top.contains(el),
    tag,
    inputType: tag === 'input' ? (lower('type') || 'text') : null,
    autocomplete: lower('autocomplete'),
    name: lower('name') + ' ' + lower('id'),
  }
}`

/** Whether a field takes a secret, which an agent never types: a password or one-time code. */
const SECRET = `(el) => {
  const lower = (name) => (el.getAttribute(name) || '').toLowerCase()
  if (el.tagName.toLowerCase() === 'input' && lower('type') === 'password') return true
  if (/one-time-code|current-password|new-password/.test(lower('autocomplete'))) return true
  return /otp|passcode|password/.test(lower('name') + ' ' + lower('id'))
}`

/**
 * Readies a field for typing as Playwright's fill does: a date, colour or range input takes its
 * value here; any other field has its text selected and focus, and Valet then inserts the text
 * with trusted input. With `keep` the text stays and the caret goes to its end (typing slowly).
 */
const FIELD = `(args) => {
  const v = globalThis.${GLOBAL}
  const found = (${ELEMENT})(args.target)
  if (found.error) return found
  if (globalThis.__valetHidden(found)) return { error: 'hidden' }
  const el = v.retarget(found, 'follow-label')
  if (!el) return { error: 'stale' }
  if ((${SECRET})(el)) return { error: 'secret' }
  try {
    if (!v.elementState(el, 'editable').matches) return { error: 'not-editable' }
  } catch (e) { return { error: 'not-editable' } }
  el.scrollIntoView({ block: 'center', inline: 'center', behavior: 'instant' })
  if (args.keep) {
    v.focusNode(el, true)
  } else {
    let result
    try { result = v.fill(el, args.value) } catch (e) { return { error: 'cannot-fill', message: String(e && e.message).slice(0, 200) } }
    if (result === 'done') return { done: true }
    if (typeof result === 'string' && result.startsWith('error:')) return { error: 'stale' }
  }
  let active = document.activeElement
  while (active && active.shadowRoot && active.shadowRoot.activeElement) active = active.shadowRoot.activeElement
  return { done: false, focused: active === el || (active !== null && el.contains(active)) }
}`

/** Chooses options in a select by value or label, as Playwright's selectOption does. */
const SELECT = `(args) => {
  const v = globalThis.${GLOBAL}
  const found = (${ELEMENT})(args.target)
  if (found.error) return found
  if (globalThis.__valetHidden(found)) return { error: 'hidden' }
  let result
  try {
    result = v.selectOptions(found, args.values.map((value) => ({ valueOrLabel: value })))
  } catch (e) { return { error: 'not-select' } }
  if (result === 'error:optionsnotfound') return { error: 'no-option' }
  if (result === 'error:optionnotenabled') return { error: 'option-disabled' }
  if (typeof result === 'string') return { error: 'stale' }
  return { selected: result.map((value) => String(value).slice(0, 200)) }
}`

/** Whether the text shows on the page, as a person would read it. */
const TEXT = `(text) => {
  const body = document.body
  const seen = body ? String(body.innerText || '') : ''
  return seen.replace(/\\s+/g, ' ').includes(text.replace(/\\s+/g, ' ').trim())
}`

export const ariaSnapshotScript = (options: {
  readonly target: string | null
  readonly depth: number | null
}): string => `(${SNAPSHOT})(${jsonLiteral(options)})`

export const ariaPointScript = (target: string): string => `(${POINT})(${jsonLiteral(target)})`

export const ariaFieldScript = (args: {
  readonly target: string
  readonly value: string
  readonly keep: boolean
}): string => `(${FIELD})(${jsonLiteral(args)})`

export const ariaSelectScript = (args: {
  readonly target: string
  readonly values: readonly string[]
}): string => `(${SELECT})(${jsonLiteral(args)})`

export const textShownScript = (text: string): string => `(${TEXT})(${jsonLiteral(text)})`

/**
 * Rewrites the snapshot's link targets (`/url:` lines, as the page wrote its href) to absolute URLs
 * against the page, so an agent can open one without working it out.
 */
export function absoluteUrls(yaml: string, base: string): string {
  return yaml.replace(/^(\s*- \/url: )(.+)$/gm, (line, lead: string, raw: string) => {
    const value = unquote(raw.trim())
    let absolute: string
    try {
      absolute = new URL(value, base).href
    } catch {
      return line
    }
    if (absolute === value) return line
    return lead + (/^[a-z]+:\/\/[\w.:/?=&%~+@-]*$/.test(absolute) ? absolute : JSON.stringify(absolute))
  })
}

function unquote(value: string): string {
  if (value.startsWith('"')) {
    try {
      return String(JSON.parse(value))
    } catch {
      return value
    }
  }
  if (value.startsWith("'") && value.endsWith("'")) return value.slice(1, -1).replaceAll("''", "'")
  return value
}

export interface AriaPoint {
  readonly x: number
  readonly y: number
  readonly covered: boolean
  readonly tag: string
  readonly inputType: string | null
  readonly autocomplete: string
  readonly name: string
}

/**
 * The lines of `next` that are new since `previous`, each with the lines it sits under, so an
 * action's answer carries only what it changed (agent-browser's --delta, Playwright MCP's
 * incremental snapshot). Empty when nothing changed.
 */
export function snapshotDelta(previous: string, next: string): string {
  const before = new Set(previous.split('\n'))
  const lines = next.split('\n')
  const keep = new Set<number>()
  lines.forEach((line, index) => {
    if (before.has(line)) return
    keep.add(index)
    // Its ancestors, so the agent can tell where on the page the change is.
    let indent = indentOf(line)
    for (let up = index - 1; up >= 0 && indent > 0; up--) {
      const own = indentOf(lines[up] ?? '')
      if (own < indent) {
        keep.add(up)
        indent = own
      }
    }
  })
  return lines.filter((_, index) => keep.has(index)).join('\n')
}

/**
 * browser_find: the snapshot's lines that match, each under its path from the top, so an agent can
 * locate an element and its ref without reading the whole page.
 */
export function findInSnapshot(
  yaml: string,
  match: { readonly text: string } | { readonly regex: RegExp },
  maxResults = 20,
): string[] {
  const lines = yaml.split('\n')
  const test =
    'text' in match
      ? (line: string) => line.toLowerCase().includes(match.text.toLowerCase())
      : (line: string) => match.regex.test(line)
  const out: string[] = []
  lines.forEach((line, index) => {
    if (out.length >= maxResults || !test(line)) return
    const path: string[] = []
    let indent = indentOf(line)
    for (let up = index - 1; up >= 0 && indent > 0; up--) {
      const candidate = lines[up] ?? ''
      const own = indentOf(candidate)
      if (own < indent) {
        path.unshift(candidate.trim())
        indent = own
      }
    }
    out.push([...path, line.trim()].join(' > '))
  })
  return out
}

function indentOf(line: string): number {
  return line.length - line.trimStart().length
}
